# Реализуйте генерацию и верификацию JWT с проверкой exp (HS256)
import time
import hmac
import hashlib
import base64
import json

def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def _b64url_decode(s: str) -> bytes:
    pad = "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s + pad)

def create_jwt(payload: dict, secret: str, ttl: int = 3600) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    body = {**payload, "exp": int(time.time()) + ttl}
    b64_h = _b64url_encode(json.dumps(header, separators=(",", ":")).encode())
    b64_p = _b64url_encode(json.dumps(body, separators=(",", ":")).encode())
    signing_input = f"{b64_h}.{b64_p}".encode("ascii")
    sig = hmac.new(secret.encode(), signing_input, hashlib.sha256).digest()
    return f"{b64_h}.{b64_p}.{_b64url_encode(sig)}"

def verify_jwt(token: str, secret: str) -> dict:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Некорректный формат JWT")
    b64_h, b64_p, b64_sig = parts
    signing_input = f"{b64_h}.{b64_p}".encode("ascii")
    expected_sig = _b64url_encode(hmac.new(secret.encode(), signing_input, hashlib.sha256).digest())
    if not hmac.compare_digest(b64_sig, expected_sig):
        raise ValueError("Подпись токена недействительна")
    payload = json.loads(_b64url_decode(b64_p))
    if payload.get("exp", 0) < time.time():
        raise ValueError("Срок действия токена истёк")
    return payload

tok = create_jwt({"sub": "user_42", "role": "admin"}, secret="super-secret", ttl=60)
decoded = verify_jwt(tok, secret="super-secret")
print("Декодированный payload:", decoded)
assert decoded["sub"] == "user_42" and decoded["role"] == "admin"

