def update_product_stock(conn, product_id, qty):
    with conn.cursor() as cur:
        cur.execute(
            'SELECT stock, version FROM products WHERE id = %s',
            (product_id,)
        )
        row = cur.fetchone()
        if not row:
            raise ValueError('Товар не найден')
        stock, version = row
        if stock < qty:
